<?phpif (!defined('BASEPATH')) exit('No direct script access allowed');class Mbommodel extends CI_Model {    function fnGetInfo($VarBom = '', $VarStatus = '', $VarId = '') {        $this->db->select('id,bomitemdesc,bomblend,bomsplreq,content,articletype,material,updatedby,status,datecreated,dateupdated');        $this->db->from(KN_MASTER_BOM);        if ($VarStatus <> '') {            $this->db->where_in('status', array($VarStatus));        } else {            $this->db->where_in('status', array(1, 2));        }        if ($VarId <> '') {            $ArrWhere['id'] = $VarId;        }        if ($VarBom <> '') {            $ArrWhere['bomitemdesc'] = $VarBom;        }        if (!empty($ArrWhere)) {            $this->db->where($ArrWhere);        }        $ArrResultList = $this->db->get()->result_array();        return $ArrResultList;    }    function fnCheck($VarData = '', $VarId = '') {        $this->db->from(KN_MASTER_BOM);        $ArrWhere = array('status' => "1");        if ($VarId <> '') {            $this->db->where_not_in('id', array($VarId));        }        if ($VarData <> '') {            $ArrWhere['bomitemdesc'] = $VarData;        }        $countAll = $this->db->where($ArrWhere)->count_all_results();        return $countAll;    }    function saveInfo($ArrUpdateData) {        $VarId = $ArrUpdateData['id'];        if ($VarId == "") {            unset($ArrUpdateData['id']);            $VarAlreadyExists = $this->fnGetInfo($ArrUpdateData['bomitemdesc'], 1);            if (empty($VarAlreadyExists)) {                $this->db->insert(KN_MASTER_BOM, $ArrUpdateData);                $VarId = $this->db->insert_id();                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = 'This item description already exists';            }        } else {            $VarAlreadyExists = $this->fnCheck($ArrUpdateData['bomitemdesc'], $VarId);            if (empty($VarAlreadyExists)) {                if ($this->db->update(KN_MASTER_BOM, $ArrUpdateData, array('id' => $VarId))) {                    $ArrResult['errcode'] = 1;                    $ArrResult['msg'] = '';                    $ArrResult['id'] = $VarId;                    $ArrResult['eid'] = urlencode(base64_encode($VarId));                } else {                    $ArrResult['errcode'] = -1;                    $ArrResult['msg'] = 'Invalid Data';                }            } else {                $ArrResult['errcode'] = -1;                $ArrResult['msg'] = 'This item description already exists';            }        }        return $ArrResult;    }    function fnCount($VarIdesc = '', $VarContent = '', $VarStatus = '', $VarBlend = '', $VarArtType = '', $Varmaterial = '', $VarSpecial = '', $VarAfilter = '') {        $userInfo = fnGetUserLoggedInfo(1);        $ArrWhere = array();        if ($VarIdesc <> '') {            $ArrWhere[] = "b.bomitemdesc like '%" . $VarIdesc . "%'";        }        if ($VarBlend <> '') {            $ArrWhere[] = "b.bomblend like '%$VarBlend%' ";        }        if ($Varmaterial <> '') {            $ArrWhere[] = "b.material like '%" . $Varmaterial . "%'";        }        if ($VarSpecial <> '') {            $ArrWhere[] = "b.bomsplreq like '%" . $VarSpecial . "%'";        }        if ($VarContent <> '') {            $ArrWhere[] = "b.content like '%" . $VarContent . "%'";        }        if ($VarArtType <> '') {            $ArrWhere[] = "b.articletype = '$VarArtType' ";        } else {            $ArrWhere[] = "b.articletype IN(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "b.bomitemdesc LIKE '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "b.status=" . $VarStatus;        } else {            $ArrWhere[] = "b.status in(1,2)";        }        $ArrWhere[] = "b.companyid = '" . $userInfo['companyid'] . "'";        $VarWhere = '';        if (!empty($ArrWhere)) {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT count(1) as trec  FROM " . KN_MASTER_BOM . " AS b INNER JOIN " . KN_USERS . " AS u ON b.updatedby = u.id WHERE " . $VarWhere;        $ObjRows = $this->db->query($VarSqlLab)->row();        return $ObjRows->trec;    }    function fnList($VarBom = '', $VarContent = '', $VarStatus = '', $VarBlend = '', $VarArtType = '', $Varmaterial = '', $VarSpecial = '', $VarLimit = 10, $offset = 0, $VarSortBy, $VarSortOrder, $VarAfilter = '') {        $userInfo = fnGetUserLoggedInfo(1);        $VarSortOrder = ($VarSortOrder == 'desc') ? 'desc' : 'asc';        $VarSortCols = array('b.bomitemdesc', 'b.bomblend', 'b.content', 'b.articletype', 'b.material', 'b.bomsplreq', 'b.status', 'u.contactname', 'b.dateupdated');        $VarSortBy = (in_array($VarSortBy, $VarSortCols)) ? $VarSortBy : 'b.dateupdated';        $VarLimitInfo = $VarLimit;        if ($offset >= 1) {            $VarLimitInfo = $offset . "," . $VarLimit;        }        $ArrWhere = array();        if ($VarBom <> '') {            $ArrWhere[] = "b.bomitemdesc like '%" . $VarBom . "%'";        }        if ($VarBlend <> '') {            $ArrWhere[] = "b.bomblend like '%$VarBlend%' ";        }        if ($Varmaterial <> '') {            $ArrWhere[] = "b.material like '%" . $Varmaterial . "%'";        }        if ($VarSpecial <> '') {            $ArrWhere[] = "b.bomsplreq like '%" . $VarSpecial . "%'";        }        if ($VarContent <> '') {            $ArrWhere[] = "b.content like '%" . $VarContent . "%'";        }        if ($VarArtType <> '') {            $ArrWhere[] = "b.articletype = '$VarArtType' ";        } else {            $ArrWhere[] = "b.articletype IN(1,2)";        }        if ($VarAfilter <> '') {            $ArrWhere[] = "b.bomitemdesc LIKE '" . $VarAfilter . "%'";        }        if ($VarStatus <> '') {            $ArrWhere[] = "b.status=" . $VarStatus;        } else {            $ArrWhere[] = "b.status in(1,2)";        }        $ArrWhere[] = "b.companyid = '" . $userInfo['companyid'] . "'";        $VarWhere = '';        if (!empty($ArrWhere)) {            $VarWhere = implode(" and ", $ArrWhere);        }        $VarSqlLab = "SELECT b.id,b.bomitemdesc,b.bomblend,b.bomsplreq,b.content,b.articletype,b.material,u.contactname,b.datecreated,b.dateupdated,b.status FROM " . KN_MASTER_BOM . " AS b INNER JOIN " . KN_USERS . " AS u ON b.updatedby = u.id WHERE " . $VarWhere . " order by " . $VarSortBy . " " . $VarSortOrder . " limit " . $VarLimitInfo;        $ObjResult = $this->db->query($VarSqlLab);        return $ObjResult;    }    function fnDel($VarId = '', $VarUpdatedBy = '') {        if (@$VarId >= 1) {            $ArrUpdateData = array('status' => 3, 'dateupdated' => date('Y-m-d H:i:s'), 'updatedby' => $VarUpdatedBy);            if ($this->db->update(KN_MASTER_BOM, $ArrUpdateData, array('id' => $VarId))) {                $ArrResult['errcode'] = 1;                $ArrResult['msg'] = '';                $ArrResult['id'] = $VarId;                $ArrResult['eid'] = urlencode(base64_encode($VarId));            } else {                $ArrResult['errcode'] = '-1';                $ArrResult['msg'] = 'Invalid Data!';            }        }        return $ArrResult;    }    function fnChangeComStat($checkboxids, $optvalue) {        $Arrids = json_decode($checkboxids, true);        $this->db->where_in('id', $Arrids);        if ($this->db->update(KN_MASTER_BOM, array('status' => $optvalue))) {            return true;        }        return false;    }}